# Weather reports and forecasts for IFR: AIM 7-1 (SIGMET, convective SIGMET, AIRMET, FIS-B, flight
# categories), Aviation Weather Handbook FAA-H-8083-28A ch. 24-27 (METAR, TAF, FB, LLWS). ACS I.B.K2.
ITEMS = [
    # ---------- Practice Test 1 ----------
    S(1, 2, "Flight categories", "A METAR reports OVC007 and 4SM BR. Which flight category is that?",
      ["IFR", "MVFR", "LIFR"],
      "IFR is a ceiling of 500 to less than 1,000 feet and/or visibility of 1 to less than 3 miles. The 700-foot ceiling makes it IFR even though the visibility is MVFR."),
    S(1, 3, "Alternate from a TAF", "Destination TAF for 1500Z to 1700Z: BKN015 OVC025, 4SM. Your ETA is 1600Z. Do you need an alternate?",
      ["Yes, the ceiling is under 2,000", "No, the visibility is over 3 SM", "No, a broken layer isn't a ceiling"],
      "A broken layer is a ceiling. With BKN015 inside the hour either side of the ETA, the 2,000-foot part of the 1-2-3 rule fails, so an alternate is required."),
    S(1, 2, "Wind shear in a TAF", "A TAF contains WS015/24045KT. What does it forecast?",
      ["Wind shear up to 1,500 feet AGL", "Surface wind of 240 at 15 knots", "Gusts to 45 knots at the surface"],
      "WS followed by three digits gives the top of a low-level wind shear layer in hundreds of feet AGL, then the wind at that height: here 240 degrees at 45 knots at 1,500 feet."),
    S(1, 2, "SIGMET validity", "An ordinary SIGMET for severe icing is normally valid for how long?",
      ["4 hours", "1 hour", "2 hours"],
      "AIM 7-1 says SIGMETs are unscheduled and valid for 4 hours, except those for tropical cyclones and volcanic ash, which run 6 hours."),
    S(1, 3, "Convective SIGMET", "Even when it doesn't say so, every convective SIGMET implies:",
      ["Severe turbulence and icing, and LLWS", "Light icing and light turbulence only", "Fog and low ceilings below 500 feet AGL"],
      "AIM 7-1 states that any convective SIGMET implies severe or greater turbulence, severe icing and low-level wind shear."),
    S(1, 2, "Datalink weather", "Your cockpit shows FIS-B radar imagery. What is it suited for?",
      ["Strategic route planning around storms", "Picking a gap between nearby cells", "Replacing a preflight weather briefing"],
      "AIM 7-1 says FIS weather supports strategic decisions about 20 minutes or more ahead. It is not for tactical avoidance, such as threading between cells, and never replaces a briefing."),
    S(1, 2, "Winds aloft", "A winds and temperatures aloft forecast shows 9900+02 for 6,000 feet. What wind is forecast?",
      ["Light and variable", "From 090 at 99 knots", "Calm, temperature unknown"],
      "In the FB forecast, 9900 means light and variable, a wind of less than 5 knots. The +02 is a temperature of plus 2 degrees C."),
    # ---------- Practice Test 2 ----------
    S(2, 2, "Flight categories", "A METAR reports BKN004 and 1 1/2SM. Which flight category is that?",
      ["LIFR", "IFR", "MVFR"],
      "LIFR is a ceiling below 500 feet and/or visibility below 1 mile. A 400-foot broken ceiling puts it in LIFR even though the visibility alone is IFR."),
    S(2, 3, "Alternate from a TAF", "Destination TAF around your 2100Z ETA: SCT020 BKN050, 3SM HZ. Do you need an alternate?",
      ["No, ceiling 5,000, visibility 3 SM", "Yes, the scattered layer is at 2,000", "Yes, visibility must be more than 3 SM"],
      "A scattered layer is not a ceiling, so the ceiling is the broken layer at 5,000 feet. Visibility of 3 SM meets the 'at least 3 SM' part of 91.169, so no alternate is needed."),
    S(2, 2, "Convective SIGMET", "Which condition alone qualifies for a convective SIGMET?",
      ["Hail of 3/4 inch at the surface", "A single cumulus over a lake", "Moderate icing in widespread stratus"],
      "Convective SIGMETs cover surface winds of 50 knots or more, hail of 3/4 inch or more at the surface, tornadoes, embedded or lines of thunderstorms, and heavy precipitation over 40 percent of a large area."),
    S(2, 2, "Convective SIGMET", "Routine convective SIGMET bulletins are issued how often?",
      ["Hourly, at 55 past", "Every 6 hours, on schedule", "Every 4 hours, on schedule"],
      "AIM 7-1: convective SIGMET bulletins are issued hourly at H+55, with special bulletins as needed. A 'CONVECTIVE SIGMET...NONE' is sent when no area qualifies."),
    S(2, 3, "AIRMET coverage", "Which AIRMET covers ceilings below 1,000 feet and extensive mountain obscuration?",
      ["Sierra", "Tango", "Zulu"],
      "AIRMET Sierra covers IFR conditions and mountain obscuration. Tango covers turbulence, strong surface winds and LLWS; Zulu covers icing and freezing levels."),
    S(2, 2, "TAF valid period", "Most US TAFs cover what period?",
      ["24 hours", "12 hours", "6 hours"],
      "TAFs are valid for 24 hours, and 30 hours at some major airports. They describe the area within 5 statute miles of the runway complex."),
    S(2, 2, "RVR in a METAR", "A METAR includes R09/2400FT. What does it report?",
      ["Runway 9 visual range of 2,400 feet", "Runway 9 is 2,400 feet long", "Ceiling of 2,400 feet over runway 9"],
      "R09/2400FT is the runway visual range for runway 9: 2,400 feet. RVR is measured along the runway, unlike prevailing visibility."),
    # ---------- Drill only ----------
    S(0, 2, "Flight categories", "Which METAR conditions are MVFR?",
      ["OVC020 and 6SM", "OVC008 and 6SM", "SKC and 2SM"],
      "MVFR is a ceiling of 1,000 to 3,000 feet and/or visibility of 3 to 5 miles. OVC008 is IFR by ceiling and 2SM is IFR by visibility."),
    S(0, 2, "AIRMET schedule", "AIRMETs over the contiguous United States are issued on what schedule?",
      ["Every 6 hours", "Every hour", "Every 12 hours"],
      "AIM 7-1: AIRMETs are scheduled every 6 hours (every 8 in Alaska), with unscheduled updates as needed."),
    S(0, 3, "SPECI", "A SPECI is issued when the surface visibility:",
      ["Drops below an approach minimum", "Changes by any amount at all", "Rises above 10 SM in clear air"],
      "The SPECI criteria include visibility dropping below 3, 2, 1, 1/2 or 1/4 SM or the lowest published approach minimum, so pilots learn of the change at once."),
    S(0, 2, "Winds aloft", "Why do FB forecasts show no temperature at the 3,000-foot level?",
      ["Temperatures start at 6,000 feet", "Winds at that level are always calm", "Only coastal stations report it"],
      "The FB forecast gives no temperature for the 3,000-foot level; temperatures begin at 6,000 feet. Above 24,000 feet they are negative and the sign is left off."),
    S(0, 3, "TAF change groups", "In a TAF, what does BECMG 1416/1418 mean?",
      ["A gradual change from 1600Z to 1800Z", "A brief change lasting under an hour", "A 40 percent chance of the conditions"],
      "BECMG describes a gradual change expected during the period given, here from 1600Z to 1800Z on the 14th, with the new conditions lasting after it. TEMPO is for brief fluctuations."),
    S(0, 2, "PIREPs", "On an IFR flight, why give ATC a PIREP of ice?",
      ["Forecasters can't measure it directly", "It closes the airway to other traffic", "It cancels the related AIRMET"],
      "Icing, turbulence, cloud tops and bases are rarely observed any other way. AIM 7-1 asks pilots to report them, and 91.183 requires reports of unforecast weather."),
    S(0, 2, "Surface analysis", "On a surface analysis chart, a blue line with triangles shows:",
      ["A cold front", "A warm front", "A stationary front"],
      "Cold fronts are blue lines with triangles pointing the way they move. Warm fronts are red with semicircles, and stationary fronts alternate the two."),
    S(0, 3, "Convective outlook", "On the SPC convective outlook, which risk is higher than SLGT?",
      ["ENH", "MRGL", "TSTM"],
      "The categories in rising order are TSTM (general thunder), MRGL, SLGT, ENH, MDT and HIGH."),
    S(0, 2, "Ceiling", "A METAR reports FEW008 SCT015 OVC030. What is the ceiling?",
      ["3,000 feet", "800 feet", "1,500 feet"],
      "A ceiling is the lowest broken or overcast layer, or a vertical visibility. FEW and SCT layers are not ceilings, so the ceiling is the overcast at 3,000 feet AGL."),
    S(0, 2, "LLWS alerts", "After a report of wind shear, how long do ATIS broadcasts keep the alert?",
      ["20 minutes", "5 minutes", "10 minutes"],
      "The Aviation Weather Handbook notes that LLWS or microburst information stays on the ATIS for 20 minutes after the last report."),
]
